/**
 * Почему STREET_TYPE_RE в addressService.ts не работает.
 *
 * В JavaScript `\w` — это [A-Za-z0-9_], кириллица в него не входит.
 * `\b` — граница между \w и не-\w. Перед словом «улица» стоит либо начало
 * строки, либо пробел (оба не-\w), а «у» — тоже не-\w. Границы нет,
 * регулярка не срабатывает НИКОГДА.
 *
 * Ровно об этом предупреждает комментарий в orgMatcher.ts:
 *   «не через \b-регэкспы — в JS \b не работает с кириллицей»
 * но в addressService.ts использованы именно они.
 */

const re = /\bул(ица)?\.?\s*/gi

const probes = [
	['улица Тверская', 'начало строки + кириллица'],
	['Тверская улица', 'пробел + кириллица'],
	['Тверская, улица', 'запятая + пробел'],
	['5ул', 'ASCII-цифра перед «ул» — граница ЕСТЬ'],
	['street улица', 'латиница + пробел'],
]

console.log('Срабатывает ли /\\bул(ица)?\\.?\\s*/gi ?\n')
for (const [s, why] of probes) {
	const out = s.replace(new RegExp(re.source, 'gi'), '')
	const hit = out !== s
	console.log(`  ${(hit ? 'ДА ' : 'НЕТ')}  ${JSON.stringify(s).padEnd(22)} -> ${JSON.stringify(out).padEnd(22)} ${why}`)
}

console.log('\nВывод: тип улицы отбрасывается только если ему предшествует')
console.log('ASCII-символ из [A-Za-z0-9_]. В реальных названиях такого не бывает,')
console.log('поэтому normalizeStreetForCompare() НЕ отбрасывает типы улиц вообще.')
